// Einmalig 2026-08-23: Nachtraeglicher Matrix-Versand fuer 22 Zusammenfassungen,
// die waehrend des 5-taegigen Matrix-Ausfalls (veraltete Raum-ID, seit 2026-08-18
// 06:06 behoben in Commit a9c53a3) nie gepostet wurden - die Zusammenfassungen selbst
// sind bereits vollstaendig in der DB vorhanden (summaryCreatedAt gesetzt,
// summaryRoomPostedAt leer), hier wird nur der fehlende Matrix-Post nachgeholt.
// Nachrichtentext 1:1 nach der Logik von 'Build Summary Message' in
// ALLRIS_P3_Bewertung nachgebaut (keine Logik neu erfunden).
const TARGET_KEYS = ["vol_10832","vol_10833","vol_10836","vol_10843","vol_10837","vol_10845","vol_10846","vol_10838","vol_10826","vol_10828","vol_10834","vol_10835","vol_10801","vol_10802","vol_10803","vol_10805","vol_10812","vol_10814","vol_10822","vol_10808","vol_10809","vol_10811"];

function parseList(value) {
  if (Array.isArray(value)) return value.filter(Boolean).map(v => String(v).trim());
  if (value === null || value === undefined || value === '') return [];
  const t = String(value).trim();
  if (!t) return [];
  try {
    const parsed = JSON.parse(t);
    if (Array.isArray(parsed)) return parsed.filter(Boolean).map(v => String(v).trim());
  } catch (e) {}
  return t.split(/\s*\|\s*/).filter(Boolean).map(v => String(v).trim());
}

const rows = $input.all().map(i => i.json).filter(r => TARGET_KEYS.includes(r.vorgangKey));
console.log('[Matrix-Nachtrag] ' + rows.length + ' von ' + TARGET_KEYS.length + ' Ziel-Zeilen gefunden.');

return rows.map(j => {
  const sentences = parseList(j.summarySentences);
  const betroffene = parseList(j.betroffene);
  const offenePunkte = parseList(j.offenePunkte);
  const unsicherheiten = parseList(j.unsicherheitenSummary);

  let vorgangsketteBlock = '';
  if (j.istFolgevorgang === true || String(j.istFolgevorgang || '').trim() === 'true') {
    let details = [];
    try { details = JSON.parse(j.vorgangsketteDetails || '[]'); } catch (e) {}
    let fehlend = [];
    try { fehlend = JSON.parse(j.fehlendeVorherigeVorgaenge || '[]'); } catch (e) {}
    const vollstaendig = j.vorgangsketteVollstaendig === true || String(j.vorgangsketteVollstaendig||'').trim()==='true';
    let ketteLines = ['', 'Bezug zu vorherigen Vorgängen:', ''];
    ketteLines.push(`* Stammvorgang: ${j.stammVorgangsnummer || ''}`);
    const beruecksichtigt = details.filter(d => d.gefunden && d.kontextVerwendet);
    const nichtBeruecksichtigt = details.filter(d => d.gefunden && !d.kontextVerwendet);
    if (beruecksichtigt.length > 0) {
      ketteLines.push('* Berücksichtigte Vorgänge:');
      for (const d of beruecksichtigt) {
        const quelleText = d.kontextQuelle === 'summary' ? 'vorhandene Zusammenfassung' : 'Dokumenttext als Fallback';
        ketteLines.push(`  * ${d.vorgangsnummer} – ${quelleText}`);
      }
    }
    if (nichtBeruecksichtigt.length > 0) {
      ketteLines.push('* Gefunden, aber in diesem Lauf nicht als Kontext verfügbar:');
      for (const d of nichtBeruecksichtigt) ketteLines.push(`  * ${d.vorgangsnummer}`);
    }
    if (fehlend.length > 0) {
      ketteLines.push('* Fehlende Vorgänge:');
      for (const vn of fehlend) ketteLines.push(`  * ${vn}`);
    }
    ketteLines.push(`* Vorgangskette vollständig: ${vollstaendig ? 'Ja' : 'Nein'}`);
    vorgangsketteBlock = ketteLines.join('\n');
  }

  let msg = `📄 Neue ALLRIS-Vorlage (nachtraeglich gesendet, Matrix-Ausfall 18.-23.08.)\n\n`;
  msg += `Titel:\n${j.title || ''}\n\n`;
  msg += `Vorgangsnummer:\n${j.vorgangsnummer || ''}\n\n`;
  msg += `Link:\n${j.allrisUrl || ''}\n\n`;
  if (vorgangsketteBlock) msg += vorgangsketteBlock + '\n\n';
  msg += `Kurzfassung:\n`;
  let summaryBlock = '';
  if (j.summaryText && String(j.summaryText).trim()) summaryBlock = String(j.summaryText).trim();
  else if (sentences.length > 0) summaryBlock = sentences.join(' ');
  else summaryBlock = '(keine Zusammenfassung)';
  summaryBlock = summaryBlock.replace(/\r\n/g, '\n').replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
  msg += summaryBlock;
  msg += `\n\nEinordnung:\n`;
  msg += `- Thema: ${j.thema || '—'}\n`;
  msg += `- Betroffene: ${betroffene.join(', ') || '—'}\n`;
  msg += `- Kosten/Haushalt: ${j.kostenHaushalt || '—'}\n`;
  msg += `- Bürgerwirkung: ${j.buergerwirkung || '—'}\n`;
  if (offenePunkte.length > 0) msg += `- Offene Punkte:\n` + offenePunkte.map(p => `  • ${p}`).join('\n') + '\n';
  if (unsicherheiten.length > 0) msg += `- Unsicherheiten:\n` + unsicherheiten.map(p => `  • ${p}`).join('\n') + '\n';

  const txnId = 'sumcatchup_' + Date.now() + '_' + (j.vorgangKey || '').replace(/[^a-zA-Z0-9]/g,'').substring(0,10);

  return { json: { ...j, summaryMessage: msg, txnId } };
});

const item = $input.item;
const j = item.json || {};
const hasError = !!(item.error || j.error || j.__error);
const eventId = j.event_id || j.eventId || '';
const matrixSuccess = !hasError && typeof eventId === 'string' && eventId.startsWith('$');
return { json: { ...j, _sentOk: matrixSuccess } };
